CREATE TABLE stores (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  status TEXT NOT NULL CHECK (status IN ('ACTIVE', 'LOCKED')),
  timezone TEXT NOT NULL DEFAULT 'Asia/Ho_Chi_Minh',
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL
);
