CREATE TABLE store_settings (
  store_id TEXT PRIMARY KEY REFERENCES stores(id),
  phone TEXT,
  address TEXT,
  currency TEXT NOT NULL DEFAULT 'VND' CHECK (currency = 'VND'),
  business_day_cutoff_minutes INTEGER NOT NULL DEFAULT 0 CHECK (
    business_day_cutoff_minutes BETWEEN 0 AND 1439
  ),
  bank_name TEXT,
  bank_account_number TEXT,
  bank_account_name TEXT,
  bank_qr_media_id TEXT,
  updated_at INTEGER NOT NULL
, province_code INTEGER, province_name TEXT, ward_code INTEGER, ward_name TEXT, location_verification_enabled INTEGER NOT NULL DEFAULT 0 CHECK (location_verification_enabled IN (0, 1)), latitude REAL CHECK (latitude IS NULL OR (latitude >= -90 AND latitude <= 90)), longitude REAL CHECK (longitude IS NULL OR (longitude >= -180 AND longitude <= 180)), allowed_radius_meters REAL NOT NULL DEFAULT 300 CHECK (allowed_radius_meters >= 30 AND allowed_radius_meters <= 5000), max_accuracy_meters REAL NOT NULL DEFAULT 100 CHECK (max_accuracy_meters >= 20 AND max_accuracy_meters <= 300), qr_location_memory_minutes INTEGER NOT NULL DEFAULT 60
  CHECK (qr_location_memory_minutes BETWEEN 5 AND 480), qr_order_cooldown_seconds INTEGER NOT NULL DEFAULT 3
  CHECK (qr_order_cooldown_seconds BETWEEN 1 AND 3600), qr_call_staff_cooldown_seconds INTEGER NOT NULL DEFAULT 60
  CHECK (qr_call_staff_cooldown_seconds BETWEEN 1 AND 3600), qr_checkout_cooldown_seconds INTEGER NOT NULL DEFAULT 60
  CHECK (qr_checkout_cooldown_seconds BETWEEN 1 AND 3600), qr_sales_schedule_enabled INTEGER NOT NULL DEFAULT 0
  CHECK (qr_sales_schedule_enabled IN (0, 1)), qr_sales_paused INTEGER NOT NULL DEFAULT 0
  CHECK (qr_sales_paused IN (0, 1)), qr_sales_paused_at INTEGER, employee_remember_session_hours INTEGER NOT NULL DEFAULT 12
  CHECK (employee_remember_session_hours BETWEEN 1 AND 720));
