CREATE TABLE products (
  id TEXT PRIMARY KEY,
  store_id TEXT NOT NULL REFERENCES stores(id),
  category_id TEXT REFERENCES categories(id),
  unit_id TEXT REFERENCES units(id),
  name TEXT NOT NULL,
  description TEXT,
  product_type TEXT NOT NULL CHECK (product_type IN ('QUANTITY', 'WEIGHT', 'TIME')),
  status TEXT NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('ACTIVE', 'DISABLED')),
  avatar_type TEXT NOT NULL DEFAULT 'COLOR' CHECK (avatar_type IN ('COLOR', 'IMAGE')),
  avatar_color TEXT,
  media_id TEXT,
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL
, is_system INTEGER NOT NULL DEFAULT 0
  CHECK (is_system IN (0, 1)), qr_order_enabled INTEGER NOT NULL DEFAULT 1
  CHECK (qr_order_enabled IN (0, 1)));
