CREATE TABLE product_variants (
  id TEXT PRIMARY KEY,
  store_id TEXT NOT NULL REFERENCES stores(id),
  product_id TEXT NOT NULL REFERENCES products(id),
  display_code TEXT NOT NULL,
  name TEXT NOT NULL,
  sale_price INTEGER CHECK (sale_price >= 0),
  cost_price INTEGER NOT NULL DEFAULT 0 CHECK (cost_price >= 0),
  prompt_price INTEGER NOT NULL DEFAULT 0 CHECK (prompt_price IN (0, 1)),
  status TEXT NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('ACTIVE', 'DISABLED')),
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL, qr_order_enabled INTEGER NOT NULL DEFAULT 1
  CHECK (qr_order_enabled IN (0, 1)),
  UNIQUE (store_id, display_code)
);
