CREATE TABLE orders (
  id TEXT PRIMARY KEY,
  store_id TEXT NOT NULL REFERENCES stores(id),
  table_id TEXT NOT NULL REFERENCES service_tables(id),
  status TEXT NOT NULL CHECK (status IN ('OPEN', 'PAYMENT_PENDING', 'PAID', 'CANCELLED')),
  version INTEGER NOT NULL DEFAULT 1,
  opened_by TEXT NOT NULL REFERENCES users(id),
  opened_at INTEGER NOT NULL,
  closed_at INTEGER,
  cancelled_at INTEGER,
  cancel_reason TEXT,
  note TEXT,
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL
, order_type TEXT NOT NULL DEFAULT 'DINE_IN'
  CHECK (order_type = 'DINE_IN'), display_code TEXT, guest_count INTEGER NOT NULL DEFAULT 1 CHECK (guest_count >= 1), customer_name TEXT, customer_phone TEXT, customer_id TEXT REFERENCES customers(id), promotion_auto_apply_suppressed INTEGER NOT NULL DEFAULT 0
  CHECK (promotion_auto_apply_suppressed IN (0, 1)));
