CREATE TABLE order_items (
  id TEXT PRIMARY KEY,
  store_id TEXT NOT NULL REFERENCES stores(id),
  order_id TEXT NOT NULL REFERENCES orders(id),
  product_id TEXT NOT NULL REFERENCES products(id),
  variant_id TEXT REFERENCES product_variants(id),
  product_type TEXT NOT NULL CHECK (product_type IN ('QUANTITY', 'WEIGHT', 'TIME')),
  product_name_snapshot TEXT NOT NULL,
  variant_name_snapshot TEXT,
  unit_name_snapshot TEXT,
  unit_price_snapshot INTEGER NOT NULL CHECK (unit_price_snapshot >= 0),
  quantity_milli INTEGER NOT NULL CHECK (quantity_milli > 0),
  discount_type TEXT CHECK (discount_type IN ('FIXED', 'PERCENT') OR discount_type IS NULL),
  discount_value INTEGER NOT NULL DEFAULT 0 CHECK (discount_value >= 0),
  line_total INTEGER NOT NULL CHECK (line_total >= 0),
  added_by TEXT NOT NULL REFERENCES users(id),
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL
, discount_input_value INTEGER, discount_amount INTEGER NOT NULL DEFAULT 0 CHECK (discount_amount >= 0), gross_line_total INTEGER NOT NULL DEFAULT 0 CHECK (gross_line_total >= 0), net_line_total INTEGER NOT NULL DEFAULT 0 CHECK (net_line_total >= 0), note TEXT, time_started_at INTEGER, time_ended_at INTEGER, source TEXT NOT NULL DEFAULT 'POS'
  CHECK (source IN ('POS', 'QR_GUEST', 'ADMIN')), source_guest_request_id TEXT, discount_reason TEXT);
