CREATE TABLE invoice_lines (
  id TEXT PRIMARY KEY,
  store_id TEXT NOT NULL REFERENCES stores(id),
  invoice_id TEXT NOT NULL REFERENCES invoices(id),
  line_type TEXT NOT NULL CHECK (line_type IN ('PRODUCT', 'TIME')),
  description TEXT NOT NULL,
  quantity_milli INTEGER NOT NULL CHECK (quantity_milli > 0),
  unit_price INTEGER NOT NULL CHECK (unit_price >= 0),
  discount_amount INTEGER NOT NULL DEFAULT 0 CHECK (discount_amount >= 0),
  line_total INTEGER NOT NULL CHECK (line_total >= 0),
  snapshot_json TEXT NOT NULL
, discount_type TEXT CHECK (discount_type IN ('FIXED', 'PERCENT') OR discount_type IS NULL), discount_input_value INTEGER, gross_line_total INTEGER NOT NULL DEFAULT 0 CHECK (gross_line_total >= 0));
