CREATE TABLE add_item_commands (
  id TEXT PRIMARY KEY,
  store_id TEXT NOT NULL REFERENCES stores(id),
  order_id TEXT NOT NULL REFERENCES orders(id),
  expected_order_version INTEGER NOT NULL,
  item_id TEXT NOT NULL,
  product_id TEXT NOT NULL REFERENCES products(id),
  variant_id TEXT REFERENCES product_variants(id),
  product_type TEXT NOT NULL,
  product_name_snapshot TEXT NOT NULL,
  variant_name_snapshot TEXT,
  unit_name_snapshot TEXT,
  unit_price_snapshot INTEGER NOT NULL,
  quantity_milli INTEGER NOT NULL,
  discount_type TEXT,
  discount_value INTEGER NOT NULL,
  line_total INTEGER NOT NULL,
  actor_user_id TEXT NOT NULL REFERENCES users(id),
  request_id TEXT NOT NULL,
  issued_at INTEGER NOT NULL, discount_input_value INTEGER, discount_amount INTEGER NOT NULL DEFAULT 0 CHECK (discount_amount >= 0), gross_line_total INTEGER NOT NULL DEFAULT 0 CHECK (gross_line_total >= 0), net_line_total INTEGER NOT NULL DEFAULT 0 CHECK (net_line_total >= 0), item_note TEXT, time_started_at INTEGER, time_ended_at INTEGER,
  UNIQUE (store_id, id)
);
