CREATE TABLE pause_time_commands (
  id TEXT PRIMARY KEY,
  store_id TEXT NOT NULL REFERENCES stores(id),
  order_id TEXT NOT NULL REFERENCES orders(id),
  expected_order_version INTEGER NOT NULL,
  pause_id TEXT NOT NULL,
  actor_user_id TEXT NOT NULL REFERENCES users(id),
  actor_session_id TEXT REFERENCES auth_sessions(id),
  device_id TEXT REFERENCES devices(id),
  request_id TEXT NOT NULL,
  issued_at INTEGER NOT NULL,
  UNIQUE (store_id, id)
);
CREATE TABLE resume_time_commands (
  id TEXT PRIMARY KEY,
  store_id TEXT NOT NULL REFERENCES stores(id),
  order_id TEXT NOT NULL REFERENCES orders(id),
  expected_order_version INTEGER NOT NULL,
  actor_user_id TEXT NOT NULL REFERENCES users(id),
  actor_session_id TEXT REFERENCES auth_sessions(id),
  device_id TEXT REFERENCES devices(id),
  request_id TEXT NOT NULL,
  issued_at INTEGER NOT NULL,
  UNIQUE (store_id, id)
);
CREATE TABLE takeaway_orders (
  id TEXT PRIMARY KEY,
  store_id TEXT NOT NULL REFERENCES stores(id),
  display_code TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'OPEN'
    CHECK (status IN ('OPEN', 'PAYMENT_PENDING', 'PAID', 'CANCELLED')),
  version INTEGER NOT NULL DEFAULT 1,
  opened_by TEXT NOT NULL REFERENCES users(id),
  opened_at INTEGER NOT NULL,
  closed_at INTEGER,
  cancelled_at INTEGER,
  cancel_reason TEXT,
  note TEXT,
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL, guest_count INTEGER NOT NULL DEFAULT 1 CHECK (guest_count >= 1), customer_name TEXT, customer_phone TEXT, customer_id TEXT REFERENCES customers(id), promotion_auto_apply_suppressed INTEGER NOT NULL DEFAULT 0
  CHECK (promotion_auto_apply_suppressed IN (0, 1)),
  UNIQUE (store_id, display_code)
);
CREATE TABLE takeaway_order_items (
  id TEXT PRIMARY KEY,
  store_id TEXT NOT NULL REFERENCES stores(id),
  order_id TEXT NOT NULL REFERENCES takeaway_orders(id),
  product_id TEXT NOT NULL REFERENCES products(id),
  variant_id TEXT REFERENCES product_variants(id),
  product_type TEXT NOT NULL CHECK (product_type IN ('QUANTITY', 'WEIGHT')),
  product_name_snapshot TEXT NOT NULL,
  variant_name_snapshot TEXT,
  unit_name_snapshot TEXT,
  unit_price_snapshot INTEGER NOT NULL CHECK (unit_price_snapshot >= 0),
  quantity_milli INTEGER NOT NULL CHECK (quantity_milli > 0),
  discount_type TEXT CHECK (discount_type IN ('FIXED', 'PERCENT') OR discount_type IS NULL),
  discount_input_value INTEGER,
  discount_amount INTEGER NOT NULL DEFAULT 0 CHECK (discount_amount >= 0),
  gross_line_total INTEGER NOT NULL CHECK (gross_line_total >= 0),
  net_line_total INTEGER NOT NULL CHECK (net_line_total >= 0),
  added_by TEXT NOT NULL REFERENCES users(id),
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL, note TEXT, discount_reason TEXT,
  CHECK (gross_line_total - discount_amount = net_line_total)
);
CREATE TABLE create_takeaway_order_commands (
  id TEXT PRIMARY KEY,
  store_id TEXT NOT NULL REFERENCES stores(id),
  order_id TEXT NOT NULL,
  display_code TEXT NOT NULL,
  note TEXT,
  actor_user_id TEXT NOT NULL REFERENCES users(id),
  request_id TEXT NOT NULL,
  issued_at INTEGER NOT NULL, business_day TEXT,
  UNIQUE (store_id, id)
);
CREATE TABLE add_takeaway_item_commands (
  id TEXT PRIMARY KEY,
  store_id TEXT NOT NULL REFERENCES stores(id),
  order_id TEXT NOT NULL REFERENCES takeaway_orders(id),
  expected_order_version INTEGER NOT NULL,
  item_id TEXT NOT NULL,
  product_id TEXT NOT NULL REFERENCES products(id),
  variant_id TEXT REFERENCES product_variants(id),
  product_type TEXT NOT NULL,
  product_name_snapshot TEXT NOT NULL,
  variant_name_snapshot TEXT,
  unit_name_snapshot TEXT,
  unit_price_snapshot INTEGER NOT NULL,
  quantity_milli INTEGER NOT NULL,
  discount_type TEXT,
  discount_input_value INTEGER,
  discount_amount INTEGER NOT NULL,
  gross_line_total INTEGER NOT NULL,
  net_line_total INTEGER NOT NULL,
  actor_user_id TEXT NOT NULL REFERENCES users(id),
  request_id TEXT NOT NULL,
  issued_at INTEGER NOT NULL, item_note TEXT,
  UNIQUE (store_id, id)
);
CREATE TABLE update_order_item_commands (
  id TEXT PRIMARY KEY,
  store_id TEXT NOT NULL REFERENCES stores(id),
  order_type TEXT NOT NULL CHECK (order_type IN ('DINE_IN', 'TAKEAWAY')),
  order_id TEXT NOT NULL,
  item_id TEXT NOT NULL,
  expected_order_version INTEGER NOT NULL,
  quantity_milli INTEGER NOT NULL CHECK (quantity_milli > 0),
  note TEXT,
  actor_user_id TEXT NOT NULL REFERENCES users(id),
  request_id TEXT NOT NULL,
  issued_at INTEGER NOT NULL, time_started_at INTEGER, time_ended_at INTEGER, variant_id TEXT, variant_name_snapshot TEXT, unit_price_snapshot INTEGER, discount_type TEXT, discount_input_value INTEGER, discount_amount INTEGER, gross_line_total INTEGER, net_line_total INTEGER,
  UNIQUE (store_id, id)
);
