CREATE TABLE update_time_range_commands (
  id TEXT PRIMARY KEY,
  store_id TEXT NOT NULL REFERENCES stores(id),
  order_id TEXT NOT NULL REFERENCES orders(id),
  expected_order_version INTEGER NOT NULL,
  previous_started_at INTEGER NOT NULL,
  previous_ended_at INTEGER,
  previous_status TEXT NOT NULL CHECK (previous_status IN ('RUNNING', 'PAUSED', 'ENDED')),
  started_at INTEGER NOT NULL,
  ended_at INTEGER,
  actor_user_id TEXT NOT NULL REFERENCES users(id),
  actor_session_id TEXT REFERENCES auth_sessions(id),
  device_id TEXT REFERENCES devices(id),
  request_id TEXT NOT NULL,
  issued_at INTEGER NOT NULL,
  CHECK (started_at <= issued_at),
  CHECK (ended_at IS NULL OR (ended_at > started_at AND ended_at <= issued_at)),
  UNIQUE (store_id, id)
);
INSERT INTO "update_time_range_commands" ("id","store_id","order_id","expected_order_version","previous_started_at","previous_ended_at","previous_status","started_at","ended_at","actor_user_id","actor_session_id","device_id","request_id","issued_at") VALUES('433b8666-085b-438c-b7ea-bddb9fa072cf','2d28f4c5-841f-4839-b233-f87e8b2d43a2','9bbf3e1a-a6b3-47c5-a53a-f206df233e34',3,1788063411581,NULL,'RUNNING',1788058311500,NULL,'7fb2878f-28ee-45dd-af12-e769c7aad9cc','86137530-9c91-49a4-99fb-959dc5cda1c5','2c81a814-3758-4756-a507-45abe4fb666c','b1397ae3-fdc8-4d1f-b3f4-7ffe6c979c7d',1788063430404);
