LOG","showHourlyUnitPrice":true,"showHourlyUnitDuration":true,"showHourlyTimeWithSeconds":false,"showItemPriceName":false,"showItemUnitPrice":true,"itemUnitPricePlacement":"SEPARATE_COLUMN","hideZeroPriceItems":false,"combineGoodsAndServiceTotal":false,"showPromotionsList":true,"showProvisionalTotal":false,"showPaymentMethod":true,"showCashDetails":false,"showBottomImage":true}}');
CREATE TABLE store_capabilities (
  store_id TEXT NOT NULL REFERENCES stores(id),
  capability TEXT NOT NULL,
  enabled INTEGER NOT NULL DEFAULT 0 CHECK (enabled IN (0, 1)),
  updated_by TEXT REFERENCES users(id),
  updated_at INTEGER NOT NULL,
  PRIMARY KEY (store_id, capability)
);
INSERT INTO "store_capabilities" ("store_id","capability","enabled","updated_by","updated_at") VALUES('2d28f4c5-841f-4839-b233-f87e8b2d43a2','POS_REALTIME',1,NULL,1787915415460);
INSERT INTO "store_capabilities" ("store_id","capability","enabled","updated_by","updated_at") VALUES('acd419d6-81e2-4290-9cae-b5ee4f74ea29','POS_REALTIME',1,NULL,1788062582408);
CREATE TABLE realtime_store_sequences (
  store_id TEXT PRIMARY KEY REFERENCES stores(id),
  last_sequence INTEGER NOT NULL CHECK (last_sequence >= 0)
);
INSERT INTO "realtime_store_sequences" ("store_id","last_sequence") VALUES('2d28f4c5-841f-4839-b233-f87e8b2d43a2',783);
INSERT INTO "realtime_store_sequences" ("store_id","last_sequence") VALUES('acd419d6-81e2-4290-9cae-b5ee4f74ea29',2);
CREATE TABLE realtime_event_requests (
  id TEXT PRIMARY KEY,
  store_id TEXT NOT NULL,
  event_type TEXT NOT NULL,
  order_id TEXT NOT NULL,
  order_version INTEGER NOT NULL,
  actor_user_id TEXT,
  device_id TEXT,
  client_mutation_id TEXT,
  request_id TEXT NOT NULL,
  topics_json TEXT NOT NULL,
  data_json TEXT NOT NULL,
  occurred_at INTEGER NOT NULL
);
CREATE TABLE create_time_session_commands (
  id TEXT PRIMARY KEY,
  store_id TEXT NOT NULL REFERENCES stores(id),
  order_id TEXT NOT NULL REFERENCES orders(id),
  time_session_id TEXT NOT NULL,
  table_id TEXT NOT NULL REFERENCES service_tables(id),
  time_product_id TEXT NOT NULL REFERENCES products(id),
  table_name_snapshot TEXT NOT NULL,
  expected_order_version INTEGER NOT NULL,
  pricing_snapshot_json TEXT NOT NULL,
  pricing_version INTEGER NOT NULL,
  unit_price_snapshot INTEGER NOT NULL CHECK (unit_price_snapshot >= 0),
  started_at INTEGER NOT NULL,
  ended_at INTEGER,
  session_status TEXT NOT NULL CHECK (session_status IN ('RUNNING', 'ENDED', 'PAUSED')),
  actor_user_id TEXT NOT NULL REFERENCES users(id),
  actor_session_id TEXT REFERENCES auth_sessions(id),
  device_id TEXT REFERENCES devices(id),
  request_id TEXT NOT NULL,
  issued_at INTEGER NOT NULL,
  UNIQUE (store_id, id),
  CHECK (started_at <= issued_at),
  CHECK (ended_at IS NULL OR (ended_at > started_at AND ended_at <= issued_at))
);
CREATE TABLE remove_time_session_commands (
  id TEXT PRIMARY KEY,
  store_id TEXT NOT NULL REFERENCES stores(id),
  order_id TEXT NOT NULL REFERENCES orders(id),
  time_session_id TEXT NOT NULL,
  expected_order_version INTEGER NOT NULL,
  reason TEXT NOT NULL,
  actor_user_id TEXT NOT NULL REFERENCES users(id),
  actor_session_id TEXT REFERENCES auth_sessions(id),
  device_id TEXT REFERENCES devices(id),
  request_id TEXT NOT NULL,
  issued_at INTEGER NOT NULL,
  UNIQUE (store_id, id)
);
CREATE TABLE table_qr_codes (
  id TEXT PRIMARY KEY,
  store_id TEXT NOT NULL REFERENCES stores(id),
  table_id TEXT NOT NULL REFERENCES service_tables(id),
  token_hash TEXT NOT NULL UNIQUE,
  version INTEGER NOT NULL DEFAULT 1 CHECK (version > 0),
  enabled INTEGER NOT NULL DEFAULT 1 CHECK (enabled IN (0, 1)),
  created_by TEXT REFERENCES users(id),
  created_at INTEGER NOT NULL,
  rotated_at INTEGER NOT NULL, public_token TEXT,
  UNIQUE (store_id, table_id)
);
INSERT INTO "table_qr_codes" ("id","store_id","table_id","token_hash","version","enabled","created_by","created_at","rotated_at","public_token") VALUES('e221ab94-640e-4a96-aa7e-ce0329b7d86c','2d28f4c5-841f-4839-b233-f87e8b2d43a2','caa5ce88-8fca-417d-a6ef-61989f06ad7a','X-0idfmPhPk0E82x0Wd3j1H70nzzPgQHGcnIkzZTOwE',1,1,'7fb2878f-28ee-45dd-af12-e769c7aad9cc',1787923763840,1787923763840,'t8r0v_61Kjf21HmKCrU9yjJg1NG2-wx8');
CREATE TABLE guest_order_sessions (
  id TEXT PRIMARY KEY,
  secret_hash TEXT NOT NULL UNIQUE,
  store_id TEXT NOT NULL REFERENCES stores(id),
  table_id TEXT NOT NULL REFERENCES service_tables(id),
  time_session_id TEXT NOT NULL REFERENCES time_sessions(id),
  qr_code_id TEXT NOT NULL REFERENCES table_qr_codes(id),
  status TEXT NOT NULL CHECK (status IN ('ACTIVE', 'EXPIRED', 'REVOKED')),
  ip_hash TEXT,
  device_nonce TEXT,
  created_at INTEGER NOT NULL,
  last_seen_at INTEGER NOT NULL,
  expires_at INTEGER NOT NULL
, location_verified_at INTEGER, location_distance_meters REAL, location_accuracy_meters REAL, location_expires_at INTEGER);
INSERT INTO "guest_order_sessions" ("id","secret_hash","store_id","table_id","time_session_id","qr_code_id","status","ip_hash","device_nonce","created_at","last_seen_at","expires_at","location_verified_at","location_distance_meters","location_accuracy_meters","location_expires_at") VALUES('ab945860-1689-4494-af2e-01b82d92986e','0LpaAI8bs5y5c0GhzimY17Tqj9Oyrg3Y_sN6A0pj6Ow','2d28f4c5-841f-4839-b233-f87e8b2d43a2','caa5ce88-8fca-417d-a6ef-61989f06ad7a','3a704c68-c9d8-4920-bafd-360898d7b768','e221ab94-640e-4a96-aa7e-ce0329b7d86c','REVOKED','MGzv9xKr9W7C1spDPxV2pb9qilwfARuAAwVxAGCsy5I',NULL,1788153611962,1788153611962,1788182411962,NULL,NULL,NULL,NULL);
CREATE TABLE guest_order_requests (
  id TEXT PRIMARY KEY,
  store_id TEXT NOT NULL REFERENCES stores(id),
  guest_session_id TEXT NOT NULL REFERENCES guest_order_sessions(id),
  table_id TEXT NOT NULL REFERENCES service_tables(id),
  time_session_id TEXT NOT NULL REFERENCES time_sessions(id),
  order_id TEXT NOT NULL REFERENCES orders(id),
  status TEXT NOT NULL CHECK (
    status IN ('PENDING', 'ACCEPTED', 'REJECTED', 'CANCELLED', 'EXPIRED')
  ),
  client_request_id TEXT NOT NULL,
  note TEXT,
  created_at INTEGER NOT NULL,
  decided_at INTEGER,
  decided_by TEXT REFERENCES users(id),
  rejected_reason TEXT, customer_name TEXT,
  UNIQUE (guest_session_id, client_request_id)
);
CREATE TABLE guest_order_request_items (
  id TEXT PRIMARY KEY,
  store_id TEXT NOT NULL REFERENCES stores(id),
  request_id TEXT NOT NULL REFERENCES guest_order_requests(id),
  product_id TEXT NOT NULL REFERENCES products(id),
  variant_id TEXT REFERENCES product_variants(id),
  product_name_snapshot TEXT NOT NULL,
  variant_name_snapshot TEXT,
  unit_name_snapshot TEXT,
  unit_price_snapshot INTEGER NOT NULL CHECK (unit_price_snapshot >= 0),
  quantity_milli INTEGER NOT NULL CHECK (quantity_milli > 0),
  gross_line_total INTEGER NOT NULL CHECK (gross_line_total >= 0),
  note TEXT,
  created_at INTEGER NOT NULL
);
CREATE TABLE create_guest_order_request_commands (
  id TEXT PRIMARY KEY,
  store_id TEXT NOT NULL REFERENCES stores(id),
  guest_session_id TEXT NOT NULL REFERENCES guest_order_sessions(id),
  table_id TEXT NOT NULL REFERENCES service_tables(id),
  time_session_id TEXT NOT NULL REFERENCES time_sessions(id),
  order_id TEXT NOT NULL REFERENCES orders(id),
  request_id TEXT NOT NULL,
  client_request_id TEXT NOT NULL,
  note TEXT,
  ip_hash TEXT,
  issued_at INTEGER NOT NULL,
  UNIQUE (guest_session_id, client_request_id)
);
CREATE TABLE accept_guest_order_request_commands (
  id TEXT PRIMARY KEY,
  store_id TEXT NOT NULL REFERENCES stores(id),
  guest_request_id TEXT NOT NULL REFERENCES guest_order_requests(id),
  expected_order_version INTEGER NOT NULL,
  actor_user_id TEXT NOT NULL REFERENCES users(id),
  actor_session_id TEXT REFERENCES auth_sessions(id),
  device_id TEXT REFERENCES devices(id),
  request_id TEXT NOT NULL,
  issued_at INTEGER NOT NULL,
  UNIQUE (store_id, id)
);
CREATE TABLE reject_guest_order_request_commands (
  id TEXT PRIMARY KEY,
  store_id TEXT NOT NULL REFERENCES stores(id),
  guest_request_id TEXT NOT NULL REFERENCES guest_order_requests(id),
  reason TEXT NOT NULL,
  actor_user_id TEXT NOT NULL REFERENCES users(id),
  actor_session_id TEXT REFERENCES auth_sessions(id),
  device_id TEXT REFERENCES devices(id),
  request_id TEXT NOT NULL,
  issued_at INTEGER NOT NULL,
  UNIQUE (store_id, id)
);
CREATE TABLE service_requests (
  id TEXT PRIMARY KEY,
  store_id TEXT NOT NULL REFERENCES stores(id),
  table_id TEXT NOT NULL REFERENCES service_tables(id),
  time_session_id TEXT NOT NULL REFERENCES time_sessions(id),
  order_id TEXT NOT NULL REFERENCES orders(id),
  guest_session_id TEXT NOT NULL REFERENCES guest_order_sessions(id),
  type TEXT NOT NULL CHECK (type IN ('CALL_STAFF', 'CHECKOUT_REQUEST')),
  status TEXT NOT NULL CHECK (status IN ('OPEN', 'ACKNOWLEDGED', 'COMPLETED', 'CANCELLED')),
  created_at INTEGER NOT NULL,
  acknowledged_at INTEGER,
  acknowledged_by TEXT REFERENCES users(id),
  completed_at INTEGER
, customer_name TEXT, reason_id TEXT REFERENCES qr_order_quick_reasons(id), reason_snapshot TEXT
  CHECK (reason_snapshot IS NULL OR length(reason_snapshot) <= 300));
CREATE TABLE push_subscriptions (
  id TEXT PRIMARY KEY,
  store_id TEXT NOT NULL REFERENCES stores(id),
  user_id TEXT NOT NULL REFERENCES users(id),
  device_id TEXT REFERENCES devices(id),
  endpoint TEXT NOT NULL UNIQUE,
  p256dh TEXT NOT NULL,
  auth TEXT NOT NULL,
  user_agent TEXT,
  created_at INTEGER NOT NULL,
  last_seen_at INTEGER NOT NULL
);
