CREATE TABLE staff_notification_events (
  id TEXT PRIMARY KEY,
  store_id TEXT NOT NULL REFERENCES stores(id),
  source_type TEXT NOT NULL CHECK (source_type IN ('GUEST_ORDER', 'SERVICE_REQUEST')),
  source_id TEXT NOT NULL,
  event_type TEXT NOT NULL CHECK (event_type IN ('QR_ORDER', 'CALL_STAFF', 'CHECKOUT_REQUEST')),
  status TEXT NOT NULL CHECK (status IN (
    'PENDING', 'OPEN', 'ACKNOWLEDGED', 'ACCEPTED', 'REJECTED',
    'COMPLETED', 'CANCELLED', 'EXPIRED'
  )),
  order_id TEXT NOT NULL,
  table_id TEXT NOT NULL,
  table_name_snapshot TEXT NOT NULL,
  area_name_snapshot TEXT NOT NULL,
  summary TEXT NOT NULL CHECK (length(summary) <= 800),
  note TEXT CHECK (note IS NULL OR length(note) <= 300),
  item_count INTEGER NOT NULL DEFAULT 0 CHECK (item_count >= 0),
  total_vnd INTEGER NOT NULL DEFAULT 0 CHECK (total_vnd >= 0),
  actor_user_id TEXT,
  actor_session_id TEXT,
  device_id TEXT,
  handled_at INTEGER,
  created_at INTEGER NOT NULL,
  expires_at INTEGER NOT NULL,
  UNIQUE (store_id, source_type, source_id)
);
CREATE TABLE table_open_requests (
  id TEXT PRIMARY KEY,
  store_id TEXT NOT NULL REFERENCES stores(id),
  table_id TEXT NOT NULL REFERENCES service_tables(id),
  qr_code_id TEXT NOT NULL REFERENCES table_qr_codes(id),
  status TEXT NOT NULL CHECK (status IN ('OPEN', 'COMPLETED', 'CANCELLED')),
  ip_hash TEXT,
  created_at INTEGER NOT NULL,
  handled_at INTEGER,
  handled_by TEXT REFERENCES users(id),
  cancel_reason TEXT
, customer_name TEXT);
CREATE TABLE customers (
  id TEXT PRIMARY KEY,
  store_id TEXT NOT NULL REFERENCES stores(id),
  name TEXT NOT NULL,
  phone TEXT NOT NULL,
  normalized_phone TEXT NOT NULL,
  email TEXT,
  birth_date TEXT,
  gender TEXT CHECK (gender IN ('MALE', 'FEMALE', 'OTHER') OR gender IS NULL),
  province_code INTEGER,
  province_name TEXT,
  ward_code INTEGER,
  ward_name TEXT,
  address_line TEXT,
  note TEXT,
  status TEXT NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('ACTIVE', 'ARCHIVED')),
  invoice_count INTEGER NOT NULL DEFAULT 0 CHECK (invoice_count >= 0),
  total_spent_vnd INTEGER NOT NULL DEFAULT 0 CHECK (total_spent_vnd >= 0),
  loyalty_points INTEGER NOT NULL DEFAULT 0,
  debt_balance_vnd INTEGER NOT NULL DEFAULT 0 CHECK (debt_balance_vnd >= 0),
  last_order_at INTEGER,
  created_by TEXT REFERENCES users(id),
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL,
  archived_at INTEGER,
  UNIQUE (store_id, normalized_phone)
);
CREATE TABLE customer_groups (
  id TEXT PRIMARY KEY,
  store_id TEXT NOT NULL REFERENCES stores(id),
  name TEXT NOT NULL,
  membership_type TEXT NOT NULL CHECK (membership_type IN ('MANUAL', 'AUTOMATIC')),
  rules_json TEXT,
  note TEXT,
  created_by TEXT REFERENCES users(id),
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL,
  UNIQUE (store_id, name COLLATE NOCASE)
);
CREATE TABLE customer_group_members (
  store_id TEXT NOT NULL REFERENCES stores(id),
  group_id TEXT NOT NULL REFERENCES customer_groups(id) ON DELETE CASCADE,
  customer_id TEXT NOT NULL REFERENCES customers(id) ON DELETE CASCADE,
  added_at INTEGER NOT NULL,
  PRIMARY KEY (group_id, customer_id)
);
CREATE TABLE customer_loyalty_settings (
  store_id TEXT PRIMARY KEY REFERENCES stores(id),
  enabled INTEGER NOT NULL DEFAULT 1 CHECK (enabled IN (0, 1)),
  vnd_per_point INTEGER NOT NULL DEFAULT 10000 CHECK (vnd_per_point > 0),
  updated_by TEXT REFERENCES users(id),
  updated_at INTEGER NOT NULL
);
CREATE TABLE customer_loyalty_entries (
  id TEXT PRIMARY KEY,
  store_id TEXT NOT NULL REFERENCES stores(id),
  customer_id TEXT NOT NULL REFERENCES customers(id),
  invoice_id TEXT,
  entry_type TEXT NOT NULL CHECK (entry_type IN ('EARN', 'REVERSAL', 'ADJUSTMENT')),
  points INTEGER NOT NULL,
  balance_after INTEGER NOT NULL,
  note TEXT,
  actor_user_id TEXT REFERENCES users(id),
  created_at INTEGER NOT NULL,
  UNIQUE (store_id, invoice_id, entry_type)
);
CREATE TABLE customer_debt_entries (
  id TEXT PRIMARY KEY,
  store_id TEXT NOT NULL REFERENCES stores(id),
  customer_id TEXT NOT NULL REFERENCES customers(id),
  invoice_id TEXT,
  entry_type TEXT NOT NULL CHECK (entry_type IN ('CHARGE', 'PAYMENT', 'ADJUSTMENT', 'REVERSAL')),
  amount_vnd INTEGER NOT NULL,
  payment_method TEXT CHECK (payment_method IN ('CASH', 'BANK_TRANSFER') OR payment_method IS NULL),
  reference TEXT,
  note TEXT,
  actor_user_id TEXT REFERENCES users(id),
  idempotency_key TEXT,
  created_at INTEGER NOT NULL,
  UNIQUE (store_id, idempotency_key)
);
CREATE TABLE invoice_payment_allocations (
  id TEXT PRIMARY KEY,
  store_id TEXT NOT NULL REFERENCES stores(id),
  invoice_id TEXT NOT NULL,
  method TEXT NOT NULL CHECK (method IN ('CASH', 'BANK_TRANSFER', 'DEBT')),
  amount_vnd INTEGER NOT NULL CHECK (amount_vnd >= 0),
  tendered_vnd INTEGER,
  created_at INTEGER NOT NULL
, bank_account_id TEXT REFERENCES store_bank_accounts(id), bank_account_snapshot_json TEXT);
