CREATE TABLE print_jobs (
  id TEXT PRIMARY KEY,
  store_id TEXT NOT NULL REFERENCES stores(id) ON DELETE CASCADE,
  target_device_id TEXT,
  printer_role TEXT NOT NULL DEFAULT 'receipt',
  document_type TEXT NOT NULL,
  document_id TEXT NOT NULL,
  idempotency_key TEXT NOT NULL,
  status TEXT NOT NULL CHECK (status IN ('QUEUED', 'CLAIMED', 'PRINTING', 'COMPLETED', 'FAILED', 'UNCERTAIN', 'CANCELLED')),
  requested_by_user_id TEXT,
  requested_by_device_id TEXT,
  claimed_by_device_id TEXT,
  created_at INTEGER NOT NULL,
  claimed_at INTEGER,
  printing_at INTEGER,
  completed_at INTEGER,
  failed_at INTEGER,
  attempt_count INTEGER NOT NULL DEFAULT 0,
  failure_code TEXT,
  failure_message TEXT
, claim_lease_expires_at INTEGER, claim_generation INTEGER NOT NULL DEFAULT 0, claim_token TEXT, claim_protocol_version INTEGER NOT NULL DEFAULT 1);
