CREATE TRIGGER trg_cancel_takeaway_order_execute
AFTER INSERT ON cancel_takeaway_order_commands
BEGIN
  UPDATE takeaway_orders
  SET status = 'CANCELLED', version = version + 1, cancelled_at = NEW.issued_at,
      cancel_reason = NEW.reason, updated_at = NEW.issued_at
  WHERE id = NEW.order_id AND store_id = NEW.store_id;
  INSERT INTO audit_logs (
    id, store_id, actor_user_id, action, entity_type, entity_id,
    request_id, after_json, created_at
  ) VALUES (
    lower(hex(randomblob(16))), NEW.store_id, NEW.actor_user_id,
    'ORDER_CANCELLED', 'ORDER', NEW.order_id, NEW.request_id,
    json_object('reason', NEW.reason), NEW.issued_at
  );
END;
CREATE TRIGGER trg_checkout_execute
AFTER INSERT ON checkout_commands
BEGIN
  INSERT INTO invoice_sequences (store_id, business_day, last_value, updated_at)
  VALUES (NEW.store_id, NEW.business_day, 1, NEW.issued_at)
  ON CONFLICT(store_id, business_day) DO UPDATE SET
    last_value = last_value + 1, updated_at = excluded.updated_at;

  UPDATE checkout_commands
  SET invoice_display_code = 'H' || substr(NEW.business_day, 3) || '-' || printf('%04d', (
    SELECT last_value FROM invoice_sequences
    WHERE store_id = NEW.store_id AND business_day = NEW.business_day
  ))
  WHERE store_id = NEW.store_id AND id = NEW.id;

  INSERT INTO payments (
    id, store_id, order_id, method, status, amount, cash_received,
    cash_change, idempotency_key, created_by, created_at
  ) VALUES (
    NEW.payment_id, NEW.store_id, NEW.order_id, NEW.method, 'SUCCEEDED',
    NEW.total, NEW.cash_received, NEW.cash_change, NEW.id,
    NEW.actor_user_id, NEW.issued_at
  );

  INSERT INTO invoices (
    id, store_id, order_id, display_code, subtotal, discount_total,
    total, status, issued_at, issued_by, snapshot_json
  ) VALUES (
    NEW.invoice_id, NEW.store_id, NEW.order_id,
    (SELECT invoice_display_code FROM checkout_commands
     WHERE store_id = NEW.store_id AND id = NEW.id),
    NEW.subtotal, NEW.discount_total, NEW.total, 'COMPLETED',
    NEW.issued_at, NEW.actor_user_id, NEW.invoice_snapshot_json
  );

  INSERT INTO invoice_lines (
    id, store_id, invoice_id, line_type, description, quantity_milli,
    unit_price, discount_amount, line_total, snapshot_json,
    discount_type, discount_input_value, gross_line_total
  )
  SELECT lower(hex(randomblob(16))), oi.store_id, NEW.invoice_id, 'PRODUCT',
    oi.product_name_snapshot, oi.quantity_milli, oi.unit_price_snapshot,
    oi.discount_amount, oi.net_line_total,
    json_object('productId', oi.product_id, 'variantId', oi.variant_id,
      'productType', oi.product_type,
      'productName', oi.product_name_snapshot, 'variantName', oi.variant_name_snapshot,
      'unitName', oi.unit_name_snapshot, 'unitPriceVnd', oi.unit_price_snapshot,
      'quantityMilli', oi.quantity_milli, 'discountType', oi.discount_type,
      'discountInputValue', oi.discount_input_value, 'discountAmountVnd', oi.discount_amount,
      'grossLineTotalVnd', oi.gross_line_total, 'netLineTotalVnd', oi.net_line_total),
    oi.discount_type, oi.discount_input_value, oi.gross_line_total
  FROM order_items oi
  WHERE oi.order_id = NEW.order_id AND oi.store_id = NEW.store_id;

  INSERT INTO invoice_lines (
    id, store_id, invoice_id, line_type, description, quantity_milli,
    unit_price, discount_amount, line_total, snapshot_json,
    discount_type, discount_input_value, gross_line_total
  )
  SELECT lower(hex(randomblob(16))), NEW.store_id, NEW.invoice_id, 'TIME',
    NEW.time_line_description, NEW.time_elapsed_seconds * 1000,
    NEW.time_amount, 0, NEW.time_amount, NEW.time_snapshot_json,
    NULL, NULL, NEW.time_amount
  WHERE NEW.time_elapsed_seconds > 0 OR NEW.time_amount > 0;

  UPDATE orders
  SET status = 'PAID', version = version + 1, closed_at = NEW.issued_at,
      updated_at = NEW.issued_at
  WHERE id = NEW.order_id AND store_id = NEW.store_id;

  UPDATE time_sessions
  SET status = 'ENDED', ended_at = NEW.issued_at, updated_at = NEW.issued_at
  WHERE order_id = NEW.order_id AND store_id = NEW.store_id;

  UPDATE service_tables
  SET status = 'AVAILABLE', version = version + 1, updated_at = NEW.issued_at
  WHERE id = NEW.table_id AND store_id = NEW.store_id;

  INSERT INTO audit_logs (
    id, store_id, actor_user_id, action, entity_type, entity_id,
    request_id, after_json, created_at
  ) VALUES (
    lower(hex(randomblob(16))), NEW.store_id, NEW.actor_user_id,
    'CHECKOUT_COMPLETED', 'INVOICE', NEW.invoice_id, NEW.request_id,
    json_object('orderId', NEW.order_id, 'subtotal', NEW.subtotal,
      'discountTotal', NEW.discount_total, 'total', NEW.total, 'method', NEW.method),
    NEW.issued_at
  );
END;
CREATE TRIGGER trg_takeaway_checkout_execute
AFTER INSERT ON takeaway_checkout_commands
BEGIN
  INSERT INTO invoice_sequences (store_id, business_day, last_value, updated_at)
  VALUES (NEW.store_id, NEW.business_day, 1, NEW.issued_at)
  ON CONFLICT(store_id, business_day) DO UPDATE SET
    last_value = last_value + 1, updated_at = excluded.updated_at;

  UPDATE takeaway_checkout_commands
  SET invoice_display_code = 'H' || substr(NEW.business_day, 3) || '-' || printf('%04d', (
    SELECT last_value FROM invoice_sequences
    WHERE store_id = NEW.store_id AND business_day = NEW.business_day
  ))
  WHERE store_id = NEW.store_id AND id = NEW.id;

  INSERT INTO takeaway_payments (
    id, store_id, order_id, method, status, amount, cash_received,
    cash_change, idempotency_key, created_by, created_at
  ) VALUES (
    NEW.payment_id, NEW.store_id, NEW.order_id, NEW.method, 'SUCCEEDED',
    NEW.total, NEW.cash_received, NEW.cash_change, NEW.id,
    NEW.actor_user_id, NEW.issued_at
  );

  INSERT INTO takeaway_invoices (
    id, store_id, order_id, display_code, subtotal, discount_total,
    total, status, issued_at, issued_by, snapshot_json
  ) VALUES (
    NEW.invoice_id, NEW.store_id, NEW.order_id,
    (SELECT invoice_display_code FROM takeaway_checkout_commands
     WHERE store_id = NEW.store_id AND id = NEW.id),
    NEW.subtotal, NEW.discount_total, NEW.total, 'COMPLETED',
    NEW.issued_at, NEW.actor_user_id, NEW.invoice_snapshot_json
  );

  INSERT INTO takeaway_invoice_lines (
    id, store_id, invoice_id, line_type, description, quantity_milli,
    unit_price, discount_type, discount_input_value, discount_amount,
    gross_line_total, line_total, snapshot_json
  )
  SELECT lower(hex(randomblob(16))), oi.store_id, NEW.invoice_id, 'PRODUCT',
    oi.product_name_snapshot, oi.quantity_milli, oi.unit_price_snapshot,
    oi.discount_type, oi.discount_input_value, oi.discount_amount,
    oi.gross_line_total, oi.net_line_total,
    json_object('productId', oi.product_id, 'variantId', oi.variant_id,
      'productType', oi.product_type,
      'productName', oi.product_name_snapshot, 'variantName', oi.variant_name_snapshot,
      'unitName', oi.unit_name_snapshot, 'unitPriceVnd', oi.unit_price_snapshot,
      'quantityMilli', oi.quantity_milli, 'note', oi.note,
      'discountAmountVnd', oi.discount_amount, 'grossLineTotalVnd', oi.gross_line_total,
      'netLineTotalVnd', oi.net_line_total)
  FROM takeaway_order_items oi
  WHERE oi.order_id = NEW.order_id AND oi.store_id = NEW.store_id;

  UPDATE takeaway_orders
  SET status = 'PAID', version = version + 1, closed_at = NEW.issued_at,
      updated_at = NEW.issued_at
  WHERE id = NEW.order_id AND store_id = NEW.store_id;

  INSERT INTO audit_logs (
    id, store_id, actor_user_id, action, entity_type, entity_id,
    request_id, after_json, created_at
  ) VALUES (
    lower(hex(randomblob(16))), NEW.store_id, NEW.actor_user_id,
    'CHECKOUT_COMPLETED', 'INVOICE', NEW.invoice_id, NEW.request_id,
    json_object('orderId', NEW.order_id, 'subtotal', NEW.subtotal,
      'discountTotal', NEW.discount_total, 'total', NEW.total, 'method', NEW.method),
    NEW.issued_at
  );
END;
CREATE TRIGGER trg_update_time_range_validate
BEFORE INSERT ON update_time_range_commands
BEGIN
  SELECT (CASE WHEN NOT EXISTS (
    SELECT 1 FROM orders o
    JOIN time_sessions ts ON ts.order_id = o.id AND ts.store_id = o.store_id
    WHERE o.id = NEW.order_id AND o.store_id = NEW.store_id
      AND o.status = 'OPEN' AND o.version = NEW.expected_order_version
      AND ts.started_at = NEW.previous_started_at
      AND ts.ended_at IS NEW.previous_ended_at
      AND ts.status = NEW.previous_status
  ) THEN RAISE(ABORT, 'ORDER_VERSION_CONFLICT') END);
END;
CREATE TRIGGER trg_transfer_table_execute
AFTER INSERT ON transfer_table_commands
BEGIN
  -- 1. Close current open segment for source table
  UPDATE table_time_segments
  SET ended_at = NEW.issued_at, updated_at = NEW.issued_at
  WHERE store_id = NEW.store_id AND order_id = NEW.order_id AND ended_at IS NULL;

  -- 2. Insert new segment for target table
  INSERT INTO table_time_segments (
    id, store_id, order_id, time_session_id, table_id, time_product_id,
    table_name_snapshot, started_at, ended_at, pricing_snapshot_json,
    pricing_version, unit_price_snapshot, created_at, updated_at
  )
  SELECT
    lower(hex(randomblob(16))), NEW.store_id, NEW.order_id, ts.id,
    target_st.id, target_st.time_product_id, COALESCE(target_st.display_name, target_st.name),
    NEW.issued_at, NULL,
    COALESCE(NEW.target_pricing_snapshot_json, ts.pricing_snapshot_json),
    COALESCE(NEW.target_pricing_version, ts.pricing_version),
    COALESCE(json_extract(COALESCE(NEW.target_pricing_snapshot_json, ts.pricing_snapshot_json), '$.basePriceVnd'), 0),
    NEW.issued_at, NEW.issued_at
  FROM time_sessions ts
  JOIN service_tables target_st ON target_st.id = NEW.target_table_id AND target_st.store_id = NEW.store_id
  WHERE ts.order_id = NEW.order_id AND ts.store_id = NEW.store_id;

  -- 3. Update orders table_id and version
  UPDATE orders
  SET table_id = NEW.target_table_id, version = version + 1, updated_at = NEW.issued_at
  WHERE id = NEW.order_id AND store_id = NEW.store_id;

  -- 4. Update time_sessions table_id, product_id, pricing
  UPDATE time_sessions
  SET table_id = NEW.target_table_id,
      time_product_id = (SELECT time_product_id FROM service_tables WHERE id = NEW.target_table_id AND store_id = NEW.store_id),
      pricing_snapshot_json = COALESCE(NEW.target_pricing_snapshot_json, pricing_snapshot_json),
      pricing_version = COALESCE(NEW.target_pricing_version, pricing_version),
      updated_at = NEW.issued_at
  WHERE order_id = NEW.order_id AND store_id = NEW.store_id;

  -- 5. Release source table to AVAILABLE
  UPDATE service_tables
  SET status = 'AVAILABLE', version = version + 1, updated_at = NEW.issued_at
  WHERE id = NEW.source_table_id AND store_id = NEW.store_id;

  -- 6. Set target table to OCCUPIED
  UPDATE service_tables
  SET status = 'OCCUPIED', version = version + 1, updated_at = NEW.issued_at
  WHERE id = NEW.target_table_id AND store_id = NEW.store_id;

  -- 7. Record audit log
  INSERT INTO audit_logs (
    id, store_id, actor_user_id, action, entity_type, entity_id,
    request_id, after_json, created_at
  ) VALUES (
    lower(hex(randomblob(16))), NEW.store_id, NEW.actor_user_id,
    'TABLE_TRANSFERRED', 'ORDER', NEW.order_id, NEW.request_id,
    json_object(
      'fromTableId', NEW.source_table_id,
      'toTableId', NEW.target_table_id,
      'orderId', NEW.order_id,
      'transferredAt', NEW.issued_at
    ),
    NEW.issued_at
  );
END;
CREATE TRIGGER trg_update_time_range_execute
AFTER INSERT ON update_time_range_commands
BEGIN
  UPDATE time_sessions
  SET started_at = NEW.started_at,
      ended_at = NEW.ended_at,
      status = CASE
        WHEN NEW.ended_at IS NOT NULL THEN 'ENDED'
        WHEN EXISTS (
          SELECT 1 FROM time_pauses tp
          WHERE tp.time_session_id = time_sessions.id AND tp.resumed_at IS NULL
        ) THEN 'PAUSED'
        ELSE 'RUNNING'
      END,
      updated_at = NEW.issued_at
  WHERE store_id = NEW.store_id AND order_id = NEW.order_id;

  UPDATE orders
  SET version = version + 1, updated_at = NEW.issued_at
  WHERE store_id = NEW.store_id AND id = NEW.order_id;

  -- Update earliest segment's started_at
  UPDATE table_time_segments
  SET started_at = NEW.started_at, updated_at = NEW.issued_at
  WHERE id = (
    SELECT id FROM table_time_segments
    WHERE store_id = NEW.store_id AND order_id = NEW.order_id
    ORDER BY started_at ASC LIMIT 1
  );

  -- Update latest segment's ended_at (if ended_at is set)
  UPDATE table_time_segments
  SET ended_at = NEW.ended_at, updated_at = NEW.issued_at
  WHERE id = (
    SELECT id FROM table_time_segments
    WHERE store_id = NEW.store_id AND order_id = NEW.order_id
    ORDER BY started_at DESC LIMIT 1
  );

  INSERT INTO audit_logs (
    id, store_id, actor_user_id, actor_session_id, device_id, action,
    entity_type, entity_id, request_id, before_json, after_json, created_at
  ) VALUES (
    lower(hex(randomblob(16))), NEW.store_id, NEW.actor_user_id,
    NEW.actor_session_id, NEW.device_id, 'TIME_RANGE_UPDATED', 'ORDER', NEW.order_id,
    NEW.request_id,
    json_object(
      'startedAtMs', NEW.previous_started_at,
      'endedAtMs', NEW.previous_ended_at,
      'status', NEW.previous_status,
      'orderVersion', NEW.expected_order_version
    ),
    json_object(
      'startedAtMs', NEW.started_at,
      'endedAtMs', NEW.ended_at,
      'status', CASE WHEN NEW.ended_at IS NULL THEN 'ACTIVE' ELSE 'ENDED' END,
      'orderVersion', NEW.expected_order_version + 1
    ),
    NEW.issued_at
  );
END;
CREATE TRIGGER trg_checkout_validate
BEFORE INSERT ON checkout_commands
BEGIN
  SELECT (CASE WHEN NOT EXISTS (
    SELECT 1 FROM orders
    WHERE id = NEW.order_id
      AND store_id = NEW.store_id
      AND table_id = NEW.table_id
      AND status IN ('OPEN', 'PAYMENT_PENDING')
      AND version = NEW.expected_order_version
  ) THEN RAISE(ABORT, 'ORDER_VERSION_CONFLICT') END);

  SELECT (CASE WHEN EXISTS (
    SELECT 1 FROM payments
    WHERE order_id = NEW.order_id AND status = 'SUCCEEDED'
  ) THEN RAISE(ABORT, 'ORDER_ALREADY_PAID') END);

  SELECT (CASE WHEN NEW.method = 'CASH' AND (
    NEW.cash_received IS NULL OR NEW.cash_received < NEW.total
  ) THEN RAISE(ABORT, 'INSUFFICIENT_CASH') END);
END;
CREATE TRIGGER trg_takeaway_checkout_validate
BEFORE INSERT ON takeaway_checkout_commands
BEGIN
  SELECT (CASE WHEN NOT EXISTS (
    SELECT 1 FROM takeaway_orders WHERE id = NEW.order_id AND store_id = NEW.store_id
      AND status IN ('OPEN', 'PAYMENT_PENDING') AND version = NEW.expected_order_version
  ) THEN RAISE(ABORT, 'ORDER_VERSION_CONFLICT') END);
  SELECT (CASE WHEN EXISTS (
    SELECT 1 FROM takeaway_payments WHERE order_id = NEW.order_id AND status = 'SUCCEEDED'
  ) THEN RAISE(ABORT, 'ORDER_ALREADY_PAID') END);
END;
CREATE TRIGGER trg_stop_time_validate
BEFORE INSERT ON stop_time_commands
BEGIN
  SELECT (CASE WHEN NOT EXISTS (
    SELECT 1 FROM orders
    WHERE id = NEW.order_id AND store_id = NEW.store_id
      AND status = 'OPEN' AND version = NEW.expected_order_version
  ) THEN RAISE(ABORT, 'ORDER_VERSION_CONFLICT') END);
END;
CREATE TRIGGER trg_resume_checkout_validate
BEFORE INSERT ON resume_checkout_commands
BEGIN
  SELECT (CASE WHEN NOT EXISTS (
    SELECT 1 FROM orders
    WHERE id = NEW.order_id AND store_id = NEW.store_id
      AND status = 'PAYMENT_PENDING' AND version = NEW.expected_order_version
  ) THEN RAISE(ABORT, 'ORDER_NOT_PAYMENT_PENDING') END);
END;
CREATE TRIGGER trg_update_order_guest_validate
BEFORE INSERT ON update_order_guest_commands
BEGIN
  SELECT (CASE WHEN NEW.order_type = 'DINE_IN' AND NOT EXISTS (
    SELECT 1 FROM orders WHERE id = NEW.order_id AND store_id = NEW.store_id
      AND status IN ('OPEN', 'PAYMENT_PENDING') AND version = NEW.expected_order_version
  ) THEN RAISE(ABORT, 'ORDER_VERSION_CONFLICT') END);
  SELECT (CASE WHEN NEW.order_type = 'TAKEAWAY' AND NOT EXISTS (
    SELECT 1 FROM takeaway_orders WHERE id = NEW.order_id AND store_id = NEW.store_id
      AND status IN ('OPEN', 'PAYMENT_PENDING') AND version = NEW.expected_order_version
  ) THEN RAISE(ABORT, 'ORDER_VERSION_CONFLICT') END);
END;
CREATE TRIGGER trg_create_time_session_validate
BEFORE INSERT ON create_time_session_commands
BEGIN
  SELECT RAISE(ABORT, 'ORDER_VERSION_CONFLICT') WHERE NOT EXISTS (
    SELECT 1 FROM orders
    WHERE id = NEW.order_id AND store_id = NEW.store_id
      AND order_type = 'DINE_IN' AND status = 'OPEN'
      AND table_id = NEW.table_id AND version = NEW.expected_order_version
  );
  SELECT RAISE(ABORT, 'TIME_SESSION_ALREADY_EXISTS') WHERE EXISTS (
    SELECT 1 FROM time_sessions WHERE order_id = NEW.order_id
  );
END;
CREATE TRIGGER trg_create_time_session_execute
AFTER INSERT ON create_time_session_commands
BEGIN
  INSERT INTO time_sessions (
    id, store_id, order_id, table_id, time_product_id, status,
    started_at, ended_at, pricing_snapshot_json, pricing_version, opened_by, updated_at
  ) VALUES (
    NEW.time_session_id, NEW.store_id, NEW.order_id, NEW.table_id, NEW.time_product_id,
    NEW.session_status, NEW.started_at, NEW.ended_at, NEW.pricing_snapshot_json,
    NEW.pricing_version, NEW.actor_user_id, NEW.issued_at
  );
  INSERT INTO table_time_segments (
    id, store_id, order_id, time_session_id, table_id, time_product_id,
    table_name_snapshot, started_at, ended_at, pricing_snapshot_json,
    pricing_version, unit_price_snapshot, created_at, updated_at
  ) VALUES (
    lower(hex(randomblob(16))), NEW.store_id, NEW.order_id, NEW.time_session_id,
    NEW.table_id, NEW.time_product_id, NEW.table_name_snapshot, NEW.started_at,
    NEW.ended_at, NEW.pricing_snapshot_json, NEW.pricing_version,
    NEW.unit_price_snapshot, NEW.issued_at, NEW.issued_at
  );
  UPDATE orders
  SET version = version + 1, updated_at = NEW.issued_at
  WHERE store_id = NEW.store_id AND id = NEW.order_id
    AND version = NEW.expected_order_version;
  INSERT INTO audit_logs (
    id, store_id, actor_user_id, actor_session_id, device_id,
    action, entity_type, entity_id, request_id, after_json, created_at
  ) VALUES (
    lower(hex(randomblob(16))), NEW.store_id, NEW.actor_user_id,
    NEW.actor_session_id, NEW.device_id, 'TIME_RANGE_CREATED', 'ORDER', NEW.order_id,
    NEW.request_id,
    json_object('startedAtMs', NEW.started_at, 'endedAtMs', NEW.ended_at), NEW.issued_at
  );
END;
