    json_object('reason', 'CANCELLED'), NEW.issued_at
  );
END;
CREATE TRIGGER trg_remove_time_session_validate
BEFORE INSERT ON remove_time_session_commands
BEGIN
  SELECT RAISE(ABORT, 'ORDER_VERSION_CONFLICT') WHERE NOT EXISTS (
    SELECT 1 FROM orders
    WHERE id = NEW.order_id AND store_id = NEW.store_id
      AND status = 'OPEN' AND version = NEW.expected_order_version
  );
  SELECT RAISE(ABORT, 'TIME_SESSION_NOT_FOUND') WHERE NOT EXISTS (
    SELECT 1 FROM time_sessions
    WHERE id = NEW.time_session_id AND order_id = NEW.order_id AND store_id = NEW.store_id
  );
END;
CREATE TRIGGER trg_remove_time_session_execute
AFTER INSERT ON remove_time_session_commands
BEGIN
  DELETE FROM time_pauses
  WHERE store_id = NEW.store_id AND time_session_id = NEW.time_session_id;
  DELETE FROM table_time_segments
  WHERE store_id = NEW.store_id AND time_session_id = NEW.time_session_id;
  DELETE FROM time_sessions
  WHERE store_id = NEW.store_id AND id = NEW.time_session_id AND order_id = NEW.order_id;
  UPDATE orders
  SET version = version + 1, updated_at = NEW.issued_at
  WHERE store_id = NEW.store_id AND id = NEW.order_id
    AND version = NEW.expected_order_version;
  INSERT INTO audit_logs (
    id, store_id, actor_user_id, actor_session_id, device_id,
    action, entity_type, entity_id, request_id, before_json, after_json, created_at
  ) VALUES (
    lower(hex(randomblob(16))), NEW.store_id, NEW.actor_user_id,
    NEW.actor_session_id, NEW.device_id, 'TIME_SESSION_REMOVED', 'TIME_SESSION',
    NEW.time_session_id, NEW.request_id,
    json_object('sessionId', NEW.time_session_id, 'orderId', NEW.order_id),
    json_object('reason', NEW.reason), NEW.issued_at
  );
END;
CREATE TRIGGER trg_rt_remove_time
AFTER INSERT ON remove_time_session_commands
BEGIN
  INSERT INTO realtime_event_requests VALUES (
    lower(hex(randomblob(16))), NEW.store_id, 'pos.order.changed', NEW.order_id,
    NEW.expected_order_version + 1, NEW.actor_user_id, NEW.device_id, NEW.id, NEW.request_id,
    json_array('pos.orders', 'pos.tables', 'pos.order:' || NEW.order_id),
    json_object('reason', 'TIME_REMOVED'), NEW.issued_at
  );
END;
CREATE TRIGGER trg_store_enable_pos_realtime
AFTER INSERT ON stores
BEGIN
  INSERT OR IGNORE INTO store_capabilities (
    store_id, capability, enabled, updated_by, updated_at
  ) VALUES (
    NEW.id, 'POS_REALTIME', 1, NULL, NEW.created_at
  );
END;
CREATE TRIGGER trg_create_guest_order_execute
AFTER INSERT ON create_guest_order_request_commands
BEGIN
  INSERT INTO guest_order_requests (
    id, store_id, guest_session_id, table_id, time_session_id, order_id,
    status, client_request_id, note, created_at
  ) VALUES (
    NEW.request_id, NEW.store_id, NEW.guest_session_id, NEW.table_id,
    NEW.time_session_id, NEW.order_id, 'PENDING', NEW.client_request_id,
    NEW.note, NEW.issued_at
  );
  INSERT INTO audit_logs (
    id, store_id, action, entity_type, entity_id, request_id, after_json, created_at
  ) VALUES (
    lower(hex(randomblob(16))), NEW.store_id, 'GUEST_ORDER_CREATED',
    'GUEST_ORDER_REQUEST', NEW.request_id, NEW.client_request_id,
    json_object('orderId', NEW.order_id, 'tableId', NEW.table_id), NEW.issued_at
  );
  INSERT INTO realtime_event_requests VALUES (
    lower(hex(randomblob(16))), NEW.store_id, 'pos.order.changed', NEW.order_id,
    (SELECT version FROM orders WHERE id = NEW.order_id), NULL, NULL,
    NEW.client_request_id, NEW.client_request_id,
    json_array('guest.orders'),
    json_object('reason', 'GUEST_ORDER_CREATED', 'guestRequestId', NEW.request_id,
      'affectedTableIds', json_array(NEW.table_id)), NEW.issued_at
  );
END;
CREATE TRIGGER trg_accept_guest_order_validate
BEFORE INSERT ON accept_guest_order_request_commands
BEGIN
  SELECT RAISE(ABORT, 'GUEST_ORDER_NOT_ACCEPTABLE') WHERE NOT EXISTS (
    SELECT 1 FROM guest_order_requests gor
    JOIN guest_order_sessions gs ON gs.id = gor.guest_session_id
    JOIN time_sessions ts ON ts.id = gor.time_session_id
    JOIN orders o ON o.id = gor.order_id
    WHERE gor.id = NEW.guest_request_id AND gor.store_id = NEW.store_id
      AND gor.status = 'PENDING' AND gs.status = 'ACTIVE'
      AND gs.expires_at > NEW.issued_at AND ts.status IN ('RUNNING', 'PAUSED')
      AND o.status = 'OPEN' AND o.version = NEW.expected_order_version
  );
END;
CREATE TRIGGER trg_reject_guest_order_validate
BEFORE INSERT ON reject_guest_order_request_commands
BEGIN
  SELECT RAISE(ABORT, 'GUEST_ORDER_ALREADY_DECIDED') WHERE NOT EXISTS (
    SELECT 1 FROM guest_order_requests
    WHERE id = NEW.guest_request_id AND store_id = NEW.store_id AND status = 'PENDING'
  );
END;
CREATE TRIGGER trg_reject_guest_order_execute
AFTER INSERT ON reject_guest_order_request_commands
BEGIN
  UPDATE guest_order_requests
  SET status = 'REJECTED', decided_at = NEW.issued_at, decided_by = NEW.actor_user_id,
      rejected_reason = NEW.reason
  WHERE id = NEW.guest_request_id AND store_id = NEW.store_id;
  INSERT INTO audit_logs (
    id, store_id, actor_user_id, actor_session_id, device_id, action,
    entity_type, entity_id, request_id, after_json, created_at
  ) VALUES (
    lower(hex(randomblob(16))), NEW.store_id, NEW.actor_user_id,
    NEW.actor_session_id, NEW.device_id, 'GUEST_ORDER_REJECTED',
    'GUEST_ORDER_REQUEST', NEW.guest_request_id, NEW.request_id,
    json_object('reason', NEW.reason), NEW.issued_at
  );
  INSERT INTO realtime_event_requests
  SELECT lower(hex(randomblob(16))), NEW.store_id, 'pos.order.changed', gor.order_id,
    (SELECT version FROM orders WHERE id = gor.order_id), NEW.actor_user_id,
    NEW.device_id, NEW.id, NEW.request_id, json_array('guest.orders'),
    json_object('reason', 'GUEST_ORDER_REJECTED', 'guestRequestId', gor.id,
      'affectedTableIds', json_array(gor.table_id)), NEW.issued_at
  FROM guest_order_requests gor WHERE gor.id = NEW.guest_request_id;
END;
CREATE TRIGGER trg_qr_revoke_on_stop_time
AFTER INSERT ON stop_time_commands
BEGIN
  UPDATE guest_order_sessions SET status = 'REVOKED'
  WHERE store_id = NEW.store_id AND time_session_id IN (
    SELECT id FROM time_sessions WHERE order_id = NEW.order_id
  ) AND status = 'ACTIVE';
  UPDATE guest_order_requests SET status = 'EXPIRED'
  WHERE store_id = NEW.store_id AND order_id = NEW.order_id AND status = 'PENDING';
  UPDATE service_requests SET status = 'CANCELLED'
  WHERE store_id = NEW.store_id AND order_id = NEW.order_id
    AND status IN ('OPEN', 'ACKNOWLEDGED');
END;
CREATE TRIGGER trg_qr_revoke_on_transfer
AFTER INSERT ON transfer_table_commands
BEGIN
  UPDATE guest_order_sessions SET status = 'REVOKED'
  WHERE store_id = NEW.store_id AND time_session_id IN (
    SELECT id FROM time_sessions WHERE order_id = NEW.order_id
  ) AND status = 'ACTIVE';
  UPDATE guest_order_requests SET status = 'EXPIRED'
  WHERE store_id = NEW.store_id AND order_id = NEW.order_id AND status = 'PENDING';
END;
CREATE TRIGGER trg_qr_revoke_on_checkout
AFTER INSERT ON checkout_commands
BEGIN
  UPDATE guest_order_sessions SET status = 'REVOKED'
  WHERE store_id = NEW.store_id AND time_session_id IN (
    SELECT id FROM time_sessions WHERE order_id = NEW.order_id
  ) AND status = 'ACTIVE';
END;
CREATE TRIGGER trg_qr_revoke_on_cancel
AFTER INSERT ON cancel_order_commands
BEGIN
  UPDATE guest_order_sessions SET status = 'REVOKED'
  WHERE store_id = NEW.store_id AND time_session_id IN (
    SELECT id FROM time_sessions WHERE order_id = NEW.order_id
  ) AND status = 'ACTIVE';
END;
CREATE TRIGGER trg_accept_guest_order_execute
AFTER INSERT ON accept_guest_order_request_commands
BEGIN
  -- Add the accepted quantities to the oldest compatible line. The correlated
  -- SUM also makes a request containing duplicate compatible items deterministic.
  UPDATE order_items
  SET quantity_milli = quantity_milli + (
        SELECT SUM(gri.quantity_milli)
        FROM guest_order_request_items gri
        JOIN products p ON p.id = gri.product_id AND p.store_id = gri.store_id
        WHERE gri.request_id = NEW.guest_request_id
          AND p.product_type <> 'TIME'
          AND gri.product_id = order_items.product_id
          AND gri.variant_id IS order_items.variant_id
          AND gri.unit_price_snapshot = order_items.unit_price_snapshot
          AND gri.note IS order_items.note
      ),
      gross_line_total = CAST((
        unit_price_snapshot * (
          quantity_milli + (
            SELECT SUM(gri.quantity_milli)
            FROM guest_order_request_items gri
            JOIN products p ON p.id = gri.product_id AND p.store_id = gri.store_id
            WHERE gri.request_id = NEW.guest_request_id
              AND p.product_type <> 'TIME'
              AND gri.product_id = order_items.product_id
              AND gri.variant_id IS order_items.variant_id
              AND gri.unit_price_snapshot = order_items.unit_price_snapshot
              AND gri.note IS order_items.note
          )
        ) + 500
      ) / 1000 AS INTEGER),
      net_line_total = CAST((
        unit_price_snapshot * (
          quantity_milli + (
            SELECT SUM(gri.quantity_milli)
            FROM guest_order_request_items gri
            JOIN products p ON p.id = gri.product_id AND p.store_id = gri.store_id
            WHERE gri.request_id = NEW.guest_request_id
              AND p.product_type <> 'TIME'
              AND gri.product_id = order_items.product_id
              AND gri.variant_id IS order_items.variant_id
              AND gri.unit_price_snapshot = order_items.unit_price_snapshot
              AND gri.note IS order_items.note
          )
        ) + 500
      ) / 1000 AS INTEGER),
      line_total = CAST((
        unit_price_snapshot * (
          quantity_milli + (
            SELECT SUM(gri.quantity_milli)
            FROM guest_order_request_items gri
            JOIN products p ON p.id = gri.product_id AND p.store_id = gri.store_id
            WHERE gri.request_id = NEW.guest_request_id
              AND p.product_type <> 'TIME'
              AND gri.product_id = order_items.product_id
              AND gri.variant_id IS order_items.variant_id
              AND gri.unit_price_snapshot = order_items.unit_price_snapshot
              AND gri.note IS order_items.note
          )
        ) + 500
      ) / 1000 AS INTEGER),
      updated_at = NEW.issued_at
  WHERE order_items.store_id = NEW.store_id
    AND order_items.order_id = (
      SELECT order_id FROM guest_order_requests WHERE id = NEW.guest_request_id
    )
    AND order_items.product_type <> 'TIME'
    AND order_items.discount_type IS NULL
    AND order_items.id = (
      SELECT existing.id
      FROM order_items existing
      WHERE existing.store_id = order_items.store_id
        AND existing.order_id = order_items.order_id
        AND existing.product_id = order_items.product_id
        AND existing.variant_id IS order_items.variant_id
        AND existing.unit_price_snapshot = order_items.unit_price_snapshot
        AND existing.note IS order_items.note
        AND existing.product_type <> 'TIME'
        AND existing.discount_type IS NULL
      ORDER BY existing.created_at, existing.id
      LIMIT 1
    )
    AND EXISTS (
      SELECT 1
      FROM guest_order_request_items gri
      JOIN products p ON p.id = gri.product_id AND p.store_id = gri.store_id
      WHERE gri.request_id = NEW.guest_request_id
        AND p.product_type <> 'TIME'
        AND gri.product_id = order_items.product_id
        AND gri.variant_id IS order_items.variant_id
        AND gri.unit_price_snapshot = order_items.unit_price_snapshot
        AND gri.note IS order_items.note
    );

  -- Insert only combinations that did not match an existing line. Grouping
  -- prevents duplicate compatible items inside one guest request as well.
  INSERT INTO order_items (
    id, store_id, order_id, product_id, variant_id, product_type,
    product_name_snapshot, variant_name_snapshot, unit_name_snapshot,
    unit_price_snapshot, quantity_milli, discount_type, discount_value,
    line_total, discount_input_value, discount_amount, gross_line_total,
    net_line_total, added_by, created_at, updated_at, note,
    time_started_at, time_ended_at, source, source_guest_request_id
  )
  SELECT
    lower(hex(randomblob(16))), gri.store_id, gor.order_id, gri.product_id,
    gri.variant_id, p.product_type, MAX(gri.product_name_snapshot),
    MAX(gri.variant_name_snapshot), MAX(gri.unit_name_snapshot),
    gri.unit_price_snapshot, SUM(gri.quantity_milli), NULL, 0,
    CAST((gri.unit_price_snapshot * SUM(gri.quantity_milli) + 500) / 1000 AS INTEGER),
    NULL, 0,
    CAST((gri.unit_price_snapshot * SUM(gri.quantity_milli) + 500) / 1000 AS INTEGER),
    CAST((gri.unit_price_snapshot * SUM(gri.quantity_milli) + 500) / 1000 AS INTEGER),
    NEW.actor_user_id, NEW.issued_at, NEW.issued_at, gri.note,
    NULL, NULL, 'QR_GUEST', gor.id
  FROM guest_order_request_items gri
  JOIN guest_order_requests gor ON gor.id = gri.request_id
  JOIN products p ON p.id = gri.product_id AND p.store_id = gri.store_id
  WHERE gri.request_id = NEW.guest_request_id
    AND NOT EXISTS (
      SELECT 1
      FROM order_items existing
      WHERE existing.store_id = gri.store_id
        AND existing.order_id = gor.order_id
        AND existing.product_id = gri.product_id
        AND existing.variant_id IS gri.variant_id
        AND existing.unit_price_snapshot = gri.unit_price_snapshot
        AND existing.note IS gri.note
        AND existing.product_type <> 'TIME'
        AND existing.discount_type IS NULL
    )
  GROUP BY gri.store_id, gor.order_id, gor.id, gri.product_id, gri.variant_id,
    p.product_type, gri.unit_price_snapshot, gri.note;

  UPDATE orders SET version = version + 1, updated_at = NEW.issued_at
  WHERE id = (SELECT order_id FROM guest_order_requests WHERE id = NEW.guest_request_id)
    AND store_id = NEW.store_id AND version = NEW.expected_order_version;

  UPDATE guest_order_requests
  SET status = 'ACCEPTED', decided_at = NEW.issued_at, decided_by = NEW.actor_user_id
  WHERE id = NEW.guest_request_id AND store_id = NEW.store_id AND status = 'PENDING';

  INSERT INTO audit_logs (
    id, store_id, actor_user_id, actor_session_id, device_id,
    action, entity_type, entity_id, request_id, after_json, created_at
  ) VALUES (
    lower(hex(randomblob(16))), NEW.store_id, NEW.actor_user_id,
    NEW.actor_session_id, NEW.device_id, 'GUEST_ORDER_ACCEPTED',
    'GUEST_ORDER_REQUEST', NEW.guest_request_id, NEW.request_id,
    json_object('orderId', (SELECT order_id FROM guest_order_requests WHERE id = NEW.guest_request_id)),
    NEW.issued_at
  );

  INSERT INTO realtime_event_requests
  SELECT lower(hex(randomblob(16))), NEW.store_id, 'pos.order.changed', gor.order_id,
    NEW.expected_order_version + 1, NEW.actor_user_id, NEW.device_id, NEW.id, NEW.request_id,
    json_array('guest.orders', 'pos.orders', 'pos.order:' || gor.order_id),
    json_object('reason', 'GUEST_ORDER_ACCEPTED', 'guestRequestId', gor.id,
      'affectedTableIds', json_array(gor.table_id)), NEW.issued_at
  FROM guest_order_requests gor WHERE gor.id = NEW.guest_request_id;
END;
CREATE TRIGGER trg_staff_notification_expire_on_stop
AFTER INSERT ON stop_time_commands
BEGIN
  UPDATE staff_notification_events
  SET status = CASE WHEN source_type = 'GUEST_ORDER' THEN 'EXPIRED' ELSE 'CANCELLED' END,
      handled_at = COALESCE(handled_at, NEW.issued_at)
  WHERE store_id = NEW.store_id AND order_id = NEW.order_id
    AND status IN ('PENDING', 'OPEN', 'ACKNOWLEDGED');
END;
CREATE TRIGGER trg_staff_notification_expire_on_transfer
AFTER INSERT ON transfer_table_commands
BEGIN
  UPDATE staff_notification_events
  SET status = CASE WHEN source_type = 'GUEST_ORDER' THEN 'EXPIRED' ELSE 'CANCELLED' END,
      handled_at = COALESCE(handled_at, NEW.issued_at)
  WHERE store_id = NEW.store_id AND order_id = NEW.order_id
    AND status IN ('PENDING', 'OPEN', 'ACKNOWLEDGED');
END;
CREATE TRIGGER trg_staff_notification_expire_on_cancel
AFTER INSERT ON cancel_order_commands
BEGIN
  UPDATE staff_notification_events
  SET status = 'CANCELLED', handled_at = COALESCE(handled_at, NEW.issued_at)
  WHERE store_id = NEW.store_id AND order_id = NEW.order_id
    AND status IN ('PENDING', 'OPEN', 'ACKNOWLEDGED');
END;
CREATE TRIGGER trg_table_open_request_realtime_created
AFTER INSERT ON table_open_requests
BEGIN
  INSERT INTO realtime_event_requests VALUES (
    lower(hex(randomblob(16))), NEW.store_id, 'pos.order.changed', NEW.table_id,
    COALESCE((SELECT version FROM service_tables WHERE id = NEW.table_id), 1),
    NULL, NULL, NEW.id, NEW.id,
    json_array('guest.table-open-requests'),
    json_object(
      'reason', 'TABLE_OPEN_REQUEST_CREATED',
      'tableOpenRequestId', NEW.id,
      'affectedTableIds', json_array(NEW.table_id)
    ),
    NEW.created_at
  );
END;
CREATE TRIGGER trg_table_open_request_realtime_updated
AFTER UPDATE OF status ON table_open_requests
WHEN OLD.status <> NEW.status
BEGIN
  INSERT INTO realtime_event_requests VALUES (
    lower(hex(randomblob(16))), NEW.store_id, 'pos.order.changed', NEW.table_id,
    COALESCE((SELECT version FROM service_tables WHERE id = NEW.table_id), 1),
    NEW.handled_by, NULL, NEW.id, NEW.id,
    json_array('guest.table-open-requests'),
    json_object(
      'reason', 'TABLE_OPEN_REQUEST_UPDATED',
      'tableOpenRequestId', NEW.id,
      'tableOpenRequestStatus', NEW.status,
      'affectedTableIds', json_array(NEW.table_id)
    ),
    COALESCE(NEW.handled_at, NEW.created_at)
  );
END;
CREATE TRIGGER trg_service_table_prevent_release_with_active_order
BEFORE UPDATE OF status ON service_tables
WHEN NEW.status = 'AVAILABLE' AND EXISTS (
  SELECT 1 FROM orders
  WHERE orders.store_id = NEW.store_id
    AND orders.table_id = NEW.id
    AND orders.status IN ('OPEN', 'PAYMENT_PENDING')
)
BEGIN
  SELECT RAISE(ABORT, 'TABLE_HAS_ACTIVE_ORDER');
END;
CREATE TRIGGER trg_update_order_guest_execute
AFTER INSERT ON update_order_guest_commands
BEGIN
  UPDATE orders
  SET guest_count = NEW.guest_count, customer_name = NEW.customer_name,
      customer_phone = NEW.customer_phone, customer_id = NEW.customer_id,
      version = version + 1, updated_at = NEW.issued_at
  WHERE NEW.order_type = 'DINE_IN' AND id = NEW.order_id AND store_id = NEW.store_id;
  UPDATE takeaway_orders
  SET guest_count = NEW.guest_count, customer_name = NEW.customer_name,
      customer_phone = NEW.customer_phone, customer_id = NEW.customer_id,
      version = version + 1, updated_at = NEW.issued_at
  WHERE NEW.order_type = 'TAKEAWAY' AND id = NEW.order_id AND store_id = NEW.store_id;
END;
CREATE TRIGGER trg_stop_time_execute
AFTER INSERT ON stop_time_commands
BEGIN
  -- 1. Close active table_time_segments (only those that are still open)
  UPDATE table_time_segments
  SET ended_at = MAX(started_at, NEW.issued_at), updated_at = MAX(started_at, NEW.issued_at)
  WHERE store_id = NEW.store_id AND order_id = NEW.order_id AND ended_at IS NULL;

  -- 2. Update time_sessions status to ENDED.
  --    Only overwrite ended_at if it has not already been set manually.
  UPDATE time_sessions
  SET
    status = 'ENDED',
    ended_at = CASE
      WHEN ended_at IS NULL THEN MAX(started_at, NEW.issued_at)
      ELSE ended_at
    END,
    updated_at = MAX(started_at, NEW.issued_at)
  WHERE store_id = NEW.store_id AND order_id = NEW.order_id;

  -- 3. Update orders status to PAYMENT_PENDING
  UPDATE orders
  SET status = 'PAYMENT_PENDING', version = version + 1, updated_at = NEW.issued_at
  WHERE id = NEW.order_id AND store_id = NEW.store_id;

  -- 4. Record audit log
  INSERT INTO audit_logs (
    id, store_id, actor_user_id, device_id, action, entity_type, entity_id,
    request_id, after_json, created_at
  ) VALUES (
    lower(hex(randomblob(16))), NEW.store_id, NEW.actor_user_id, NEW.device_id,
    'ORDER_CHECKOUT_PENDING', 'ORDER', NEW.order_id, NEW.request_id,
    json_object('orderId', NEW.order_id, 'stoppedAt', NEW.issued_at),
    NEW.issued_at
  );
END;
CREATE TRIGGER trg_checkout_payment_snapshot_validate
BEFORE INSERT ON checkout_commands
WHEN NEW.payment_snapshot_id IS NOT NULL
BEGIN
