    WHERE ps.id = NEW.payment_snapshot_id
      AND ps.store_id = NEW.store_id
      AND ps.order_id = NEW.order_id
      AND ps.order_type = 'DINE_IN'
      AND ps.order_version = NEW.expected_order_version
      AND ps.status = 'ACTIVE'
