CREATE TRIGGER trg_create_guest_order_validate
BEFORE INSERT ON create_guest_order_request_commands
BEGIN
  SELECT RAISE(ABORT, 'TABLE_SESSION_NOT_ACTIVE') WHERE NOT EXISTS (
    SELECT 1 FROM guest_order_sessions gs
    JOIN time_sessions ts ON ts.id = gs.time_session_id AND ts.store_id = gs.store_id
    JOIN orders o ON o.id = ts.order_id AND o.store_id = ts.store_id
    JOIN service_tables st ON st.id = gs.table_id AND st.store_id = gs.store_id
    WHERE gs.id = NEW.guest_session_id AND gs.store_id = NEW.store_id
      AND gs.table_id = NEW.table_id AND gs.time_session_id = NEW.time_session_id
      AND ts.order_id = NEW.order_id AND gs.status = 'ACTIVE'
      AND gs.expires_at > NEW.issued_at AND ts.status IN ('RUNNING', 'PAUSED')
      AND o.status = 'OPEN' AND st.qr_order_enabled = 1
  );
  SELECT RAISE(ABORT, 'GUEST_ORDER_TOO_FAST') WHERE EXISTS (
    SELECT 1 FROM guest_order_requests gor
    JOIN store_settings ss ON ss.store_id = gor.store_id
    WHERE gor.guest_session_id = NEW.guest_session_id
      AND gor.created_at > NEW.issued_at - (ss.qr_order_cooldown_seconds * 1000)
  );
  SELECT RAISE(ABORT, 'GUEST_ORDER_RATE_LIMITED') WHERE (
    SELECT COUNT(*) FROM guest_order_requests
    WHERE guest_session_id = NEW.guest_session_id AND created_at > NEW.issued_at - 60000
  ) >= 5;
  SELECT RAISE(ABORT, 'TABLE_ORDER_RATE_LIMITED') WHERE (
    SELECT COUNT(*) FROM guest_order_requests
    WHERE store_id = NEW.store_id AND table_id = NEW.table_id
      AND created_at > NEW.issued_at - 300000
  ) >= 10;
  SELECT RAISE(ABORT, 'GUEST_IP_RATE_LIMITED') WHERE NEW.ip_hash IS NOT NULL AND (
    SELECT COUNT(*) FROM guest_order_requests gor
    JOIN guest_order_sessions gs ON gs.id = gor.guest_session_id
    WHERE gs.ip_hash = NEW.ip_hash AND gor.created_at > NEW.issued_at - 60000
  ) >= 60;
END;
CREATE TRIGGER trg_resume_checkout_execute
AFTER INSERT ON resume_checkout_commands
BEGIN
  -- Resuming checkout also closes a genuine manual pause that was active when
  -- checkout began. Its elapsed interval remains excluded from billing.
  UPDATE time_pauses
  SET resumed_at = NEW.issued_at
  WHERE store_id = NEW.store_id
    AND resumed_at IS NULL
    AND time_session_id IN (
      SELECT ts.id
      FROM time_sessions ts
      JOIN stop_time_commands stopped
        ON stopped.id = (
          SELECT id
          FROM stop_time_commands
          WHERE store_id = NEW.store_id AND order_id = NEW.order_id
            AND issued_at <= NEW.issued_at
          ORDER BY issued_at DESC, id DESC LIMIT 1
        )
      WHERE ts.store_id = NEW.store_id AND ts.order_id = NEW.order_id
        AND ts.ended_at >= stopped.issued_at
    );

  -- Reopen the existing table/rate segment. This keeps both the UI breakdown
  -- and the pricing calculation on one continuous interval.
  UPDATE table_time_segments
  SET ended_at = NULL, updated_at = NEW.issued_at
  WHERE id IN (
    SELECT tts.id
    FROM table_time_segments tts
    JOIN time_sessions ts
      ON ts.id = tts.time_session_id
      AND ts.store_id = tts.store_id
      AND ts.order_id = tts.order_id
    JOIN stop_time_commands stopped
      ON stopped.id = (
        SELECT id
        FROM stop_time_commands
        WHERE store_id = NEW.store_id AND order_id = NEW.order_id
          AND issued_at <= NEW.issued_at
        ORDER BY issued_at DESC, id DESC LIMIT 1
      )
    WHERE tts.store_id = NEW.store_id AND tts.order_id = NEW.order_id
      AND ts.ended_at >= stopped.issued_at
    ORDER BY tts.started_at DESC, tts.id DESC LIMIT 1
  );

  -- Defensive fallback for legacy sessions that have no table segment.
  INSERT INTO table_time_segments (
    id, store_id, order_id, time_session_id, table_id, time_product_id,
    table_name_snapshot, started_at, ended_at, pricing_snapshot_json,
    pricing_version, unit_price_snapshot, created_at, updated_at
  )
  SELECT
    lower(hex(randomblob(16))), NEW.store_id, NEW.order_id, ts.id,
    ts.table_id, ts.time_product_id, COALESCE(st.display_name, st.name),
    ts.started_at, NULL, ts.pricing_snapshot_json, ts.pricing_version,
    COALESCE(json_extract(ts.pricing_snapshot_json, '$.basePriceVnd'), 0),
    NEW.issued_at, NEW.issued_at
  FROM time_sessions ts
  JOIN service_tables st
    ON st.id = ts.table_id AND st.store_id = NEW.store_id
  JOIN stop_time_commands stopped
    ON stopped.id = (
      SELECT id
      FROM stop_time_commands
      WHERE store_id = NEW.store_id AND order_id = NEW.order_id
        AND issued_at <= NEW.issued_at
      ORDER BY issued_at DESC, id DESC LIMIT 1
    )
  WHERE ts.store_id = NEW.store_id AND ts.order_id = NEW.order_id
    AND ts.ended_at >= stopped.issued_at
    AND NOT EXISTS (
      SELECT 1
      FROM table_time_segments
      WHERE store_id = NEW.store_id AND order_id = NEW.order_id
    );

  -- A manually-entered end time predating checkout remains authoritative.
  UPDATE time_sessions
  SET status = 'RUNNING', ended_at = NULL, updated_at = NEW.issued_at
  WHERE store_id = NEW.store_id AND order_id = NEW.order_id
    AND ended_at >= (
      SELECT issued_at
      FROM stop_time_commands
      WHERE store_id = NEW.store_id AND order_id = NEW.order_id
        AND issued_at <= NEW.issued_at
      ORDER BY issued_at DESC, id DESC LIMIT 1
    );

  UPDATE orders
  SET status = 'OPEN', version = version + 1, updated_at = NEW.issued_at
  WHERE id = NEW.order_id AND store_id = NEW.store_id;

  INSERT INTO audit_logs (
    id, store_id, actor_user_id, device_id, action, entity_type, entity_id,
    request_id, after_json, created_at
  ) VALUES (
    lower(hex(randomblob(16))), NEW.store_id, NEW.actor_user_id, NEW.device_id,
    'ORDER_RESUMED_FROM_CHECKOUT', 'ORDER', NEW.order_id, NEW.request_id,
    json_object('orderId', NEW.order_id, 'resumedAt', NEW.issued_at,
      'continuousBilling', 1), NEW.issued_at
  );
END;
CREATE TRIGGER trg_realtime_event_request_execute
AFTER INSERT ON realtime_event_requests
BEGIN
  INSERT OR IGNORE INTO realtime_store_sequences (store_id, last_sequence)
  SELECT NEW.store_id, 0
  WHERE NOT EXISTS (
    SELECT 1 FROM store_capabilities
    WHERE store_id = NEW.store_id AND capability = 'POS_REALTIME' AND enabled = 0
  );

  UPDATE realtime_store_sequences
  SET last_sequence = last_sequence + 1
  WHERE store_id = NEW.store_id AND NOT EXISTS (
    SELECT 1 FROM store_capabilities
    WHERE store_id = NEW.store_id AND capability = 'POS_REALTIME' AND enabled = 0
  );

  INSERT INTO realtime_events (
    event_id, store_id, sequence, schema_version, event_type,
    aggregate_type, aggregate_id, aggregate_version,
    actor_kind, actor_user_id, device_id, client_mutation_id, request_id,
    topics_json, data_json, occurred_at
  )
  SELECT
    NEW.id, NEW.store_id, sequence.last_sequence, 1, NEW.event_type,
    'ORDER', NEW.order_id, NEW.order_version,
    CASE
      WHEN NEW.actor_user_id IS NULL THEN NULL
      WHEN EXISTS (SELECT 1 FROM pin_verifiers WHERE user_id = NEW.actor_user_id)
        THEN 'EMPLOYEE'
      ELSE 'OWNER'
    END,
    NEW.actor_user_id, NEW.device_id, NEW.client_mutation_id, NEW.request_id,
    NEW.topics_json, NEW.data_json, NEW.occurred_at
  FROM realtime_store_sequences sequence
  WHERE sequence.store_id = NEW.store_id
    AND NOT EXISTS (
      SELECT 1 FROM store_capabilities
      WHERE store_id = NEW.store_id AND capability = 'POS_REALTIME' AND enabled = 0
    );

  DELETE FROM realtime_event_requests WHERE id = NEW.id;
END;
CREATE TRIGGER trg_print_config_change_execute
AFTER INSERT ON print_config_change_requests
BEGIN
  INSERT OR IGNORE INTO store_print_config_versions (store_id, version)
  VALUES (NEW.store_id, 0);

  UPDATE store_print_config_versions
  SET version = version + 1
  WHERE store_id = NEW.store_id;

  INSERT INTO realtime_store_sequences (store_id, last_sequence)
  VALUES (NEW.store_id, 1)
  ON CONFLICT (store_id) DO UPDATE SET last_sequence = last_sequence + 1;

  INSERT INTO realtime_events (
    event_id, store_id, sequence, schema_version, event_type,
    aggregate_type, aggregate_id, aggregate_version,
    actor_kind, actor_user_id, device_id, client_mutation_id, request_id,
    topics_json, data_json, occurred_at
  ) VALUES (
    NEW.id,
    NEW.store_id,
    (SELECT last_sequence FROM realtime_store_sequences WHERE store_id = NEW.store_id),
    1,
    'pos.print_config.updated',
    'STORE',
    NEW.store_id,
    (SELECT version FROM store_print_config_versions WHERE store_id = NEW.store_id),
    CASE
      WHEN NEW.actor_user_id IS NULL THEN NULL
      WHEN EXISTS (SELECT 1 FROM pin_verifiers WHERE user_id = NEW.actor_user_id)
        THEN 'EMPLOYEE'
      WHEN EXISTS (SELECT 1 FROM users WHERE id = NEW.actor_user_id)
        THEN 'OWNER'
      ELSE NULL
    END,
    (SELECT id FROM users WHERE id = NEW.actor_user_id),
    (SELECT id FROM devices WHERE id = NEW.device_id),
    NULL,
    NEW.request_id,
    json_array('pos.print_config'),
    json_object(
      'reason', 'PRINT_CONFIG_UPDATED',
      'configVersion',
      (SELECT version FROM store_print_config_versions WHERE store_id = NEW.store_id)
    ),
    NEW.occurred_at
  );

  DELETE FROM print_config_change_requests WHERE id = NEW.id;
END;
CREATE TRIGGER trg_pos_performance_rate_limit
BEFORE INSERT ON pos_performance_sessions
BEGIN
  SELECT RAISE(ABORT, 'POS_PERFORMANCE_RATE_LIMITED') WHERE (
    SELECT COUNT(*) FROM pos_performance_sessions
    WHERE device_key = NEW.device_key
      AND received_at > NEW.received_at - 3600000
  ) >= 60;
END;
CREATE TRIGGER trg_open_table_execute
AFTER INSERT ON open_table_commands
BEGIN
  INSERT INTO orders (
    id, store_id, table_id, status, version, opened_by, opened_at, created_at, updated_at
  ) VALUES (
    NEW.order_id, NEW.store_id, NEW.table_id, 'OPEN', 1,
    NEW.actor_user_id, NEW.issued_at, NEW.issued_at, NEW.issued_at
  );

  INSERT INTO time_sessions (
    id, store_id, order_id, table_id, time_product_id, status, started_at,
    pricing_snapshot_json, pricing_version, opened_by, updated_at
  )
  SELECT
    NEW.time_session_id, NEW.store_id, NEW.order_id, st.id, st.time_product_id,
    'RUNNING', NEW.issued_at, NEW.pricing_snapshot_json, NEW.pricing_version,
    NEW.actor_user_id, NEW.issued_at
  FROM service_tables st WHERE st.id = NEW.table_id AND st.store_id = NEW.store_id;

  INSERT INTO table_time_segments (
    id, store_id, order_id, time_session_id, table_id, time_product_id,
    table_name_snapshot, started_at, ended_at, pricing_snapshot_json,
    pricing_version, unit_price_snapshot, created_at, updated_at
  )
  SELECT
    lower(hex(randomblob(16))), NEW.store_id, NEW.order_id, NEW.time_session_id,
    st.id, st.time_product_id, COALESCE(st.display_name, st.name), NEW.issued_at, NULL,
    NEW.pricing_snapshot_json, NEW.pricing_version,
    COALESCE(json_extract(NEW.pricing_snapshot_json, '$.basePriceVnd'), 0),
    NEW.issued_at, NEW.issued_at
  FROM service_tables st WHERE st.id = NEW.table_id AND st.store_id = NEW.store_id;

  UPDATE service_tables
  SET status = 'OCCUPIED', version = version + 1, updated_at = NEW.issued_at
  WHERE id = NEW.table_id AND store_id = NEW.store_id;
END;
